        return str(tools.get_portfolio(account)["total_value"])

    # Everything else: retrieve documents and ask the solver once.
    docs = tools.search(question, k=4)
    context = "\n".join("- " + d["text"] for d in docs)
    prompt = (
        "Use the documents to answer the question.\n"
        f"Documents:\n{context}\n\n"
        f"Question: {question}\n"
        "Reply with only the final number (no units, no words)."
    )
    return tools.llm(prompt, max_tokens=24).strip()


def handle_d162e3(question, tools):
    """
    Wrapper that verifies/repairs the answer from `run`.
    Returns the final answer string or None if `run` should be called.
    """
    raw_answer = run(question, tools)

    if raw_answer is None:
        return None

    # 1. Basic validation: if answer is '0', 'Not enough information', or 'None',
    #    we suspect a retrieval failure or LLM hallucination and try to re-evaluate.
    stripped = raw_answer.strip()
    if stripped in ("0", "Not enough information", "None", "NaN", "inf", "infinity"):
        # Try a more targeted search if the question mentions a company and a metric.
        # Heuristic: if the question asks for a specific metric (revenue, net_income) for a known entity,
        # try to extract the ticker and get financials directly.
        entity = None
        metric = None
        period = None

        # Detect English pattern: "What was the FY<year> revenue of <Company>?"
        m_eng = re.search(r"FY(\d{4})\s+(revenue|net_income|parent.*revenue).*?(\w+)", question, re.IGNORECASE)
        if m_eng:
            period = "FY" + m_eng.group(1)
            metric = "revenue" if "revenue" in m_eng.group(2).lower() else "net_income"
            # Extract company name (last word before punctuation)
            parts = m_eng.group(3).split()
            entity = parts[-1] if parts else None
        else:
            # Try Arabic pattern: "كم بلغت ... <metric> شركة <name> ..."
            m_ar = re.search(r"(صافي ربح|إيرادات).*?شركة\s+(\w+)", question)
            if m_ar:
                metric = "net_income" if "صافي ربح" in m_ar.group(1) else "revenue"
                entity = m_ar.group(2)
                # Try to infer period from "عام 2023" or "FY2024"
                if "2024" in question:
                    period = "FY2024"
                elif "2023" in question:
                    period = "FY2023"

        if entity and metric:
            try:
                ticker = tools.lookup_ticker(entity)
                if ticker:
                    val = tools.get_financials(ticker, metric, period)
                    if "value" in val:
                        return str(val["value"])
            except Exception:
                pass

        # If still ambiguous, try a second LLM pass with the same context but stricter prompt
        docs = tools.search(question, k=6)
        context = "\n".join("- " + d["text"] for d in docs)
        prompt2 = (
            "Use the documents to answer the question.\n"
            f"Documents:\n{context}\n\n"
            f"Question: {question}\n"
            "Reply with only the final number (no units, no words). If unsure, say 'UNKNOWN'."
        )
        raw_answer2 = tools.llm(prompt2, max_tokens=64).strip()
        if raw_answer2 and raw_answer2 not in ("UNKNOWN", "0", "None"):
            return raw_answer2

        # If still failing, return original '0' as a fallback or re-raise if needed.
        # For this harness, we return the original '0' but mark it as likely wrong.
        return raw_answer

    # 2. Arithmetic verification: if the answer looks like a simple calculation result,
    #    try to reconstruct the expression from the context (simplified).
    #    Since full expression parsing is hard, we check if the number is reasonable
    #    by seeing if it appears in the context documents.
    if stripped.replace(".", "").replace("-", "").isdigit():
        # Normalize to float
        try:
            num = float(stripped)
            # Check if this number appears in the context (case-insensitive, allow decimals)
            context_lower = context.lower()
            if str(num).lower() in context_lower or f"{num:.1f}".lower() in context_lower:
                return stripped
            # If not found in context, try to find similar numbers in context
            matches = re.findall(r"-?\d+\.?\d*", context)
            found_similar = False
            for m in matches:
                try:
                    m_val = float(m)
                    if abs(m_val - num) / (abs(num) + 1e-9) < 0.01: # 1% tolerance
                        return str(m_val)
                except:
                    pass
            if found_similar:
                return stripped
        except:
            pass

    # 3. Growth questions: check if the answer is a percentage (e.g., 23.81)
    #    and if the context mentions a similar percentage.
    if "%" in question.lower() or "percent" in question.lower() or "change" in question.lower():
        try:
            num = float(stripped)
            # Look for similar percentages in context
            pct_matches = re.findall(r"-?\d+\.?\d*%", context)
            if pct_matches:
                for pm in pct_matches:
                    try:
                        pm_val = float(pm)
                        if abs(pm_val - num) < 1.0: # 1% tolerance roughly
                            return pm
                    except:
                        pass
        except:
            pass

    # If verification fails but we have a plausible number, return it anyway
    # to avoid breaking working cases with overly strict checks.
    return raw_answer


def run(question, tools):
    try:
        answer = handle_d162e3(question, tools)
    except Exception:
        answer = None
    if answer is not None:
        return str(answer)
    return run_prev_d162e3(question, tools)
